mapper.update:
update abr_assessment a set visitor_id = #{toId}
where a.visitor_id = #{fromId}
  and not exists (select 1 from abr_assessment b where b.visitor_id = #{toId} and b.request_id = a.request_id)

update abr_plan_item a set visitor_id = #{toId}, app_user_id = #{appUserId}
where a.visitor_id = #{fromId}
  and not exists (select 1 from abr_plan_item b where b.visitor_id = #{toId} and b.program_id = a.program_id)

update abr_plan_material a set visitor_id = #{toId}, app_user_id = #{appUserId}
where a.visitor_id = #{fromId}
  and not exists (select 1 from abr_plan_material b where b.visitor_id = #{toId} and b.material_key = a.material_key)

update abr_share a set visitor_id = #{toId}, update_time = now()
where a.visitor_id = #{fromId}
  and not exists (select 1 from abr_share b where b.visitor_id = #{toId} and b.kind = a.kind and b.ref_id = a.ref_id)

update abr_event a set visitor_id = #{toId}, app_user_id = #{appUserId}
where a.visitor_id = #{fromId}
  and (a.dedup_key is null
       or not exists (select 1 from abr_event b where b.visitor_id = #{toId} and b.event_type = a.event_type and b.dedup_key = a.dedup_key))
